/**
 * frontend/src/components/CameraRecognition.jsx
 * Version finale optimisée - Caméra PC + Contrôle manuel + Intervalle adaptatif
 */

import React, { useState, useRef, useEffect, useCallback } from 'react';
import axios from 'axios';

const CAPTURE_INTERVAL_DEFAULT = 1500;
const CAPTURE_INTERVAL_FAST = 600;
const CONFIDENCE_THRESHOLD = 0.5;

const COLORS = {
  primary: '#4F46E5',
  success: '#10B981',
  warning: '#F59E0B',
  error: '#EF4444',
  gray: '#64748B',
  textMain: '#1E293B',
  textMuted: '#64748B',
  border: '#E2E8F0',
  background: '#F8FAFC',
};

const CameraRecognition = ({ addNotification }) => {
  // ==================== REFS ====================
  const videoRef = useRef(null);
  const overlayCanvasRef = useRef(null);     // Pour dessiner le face box
  const streamRef = useRef(null);
  const timeoutRef = useRef(null);

  // ==================== STATES ====================
  const [cameraActive, setCameraActive] = useState(false);
  const [autoMode, setAutoMode] = useState(false);
  const [loading, setLoading] = useState(false);
  const [status, setStatus] = useState('idle'); // idle, scanning, success, warning, error

  const [capturedImage, setCapturedImage] = useState(null);
  const [registeredPhotoUrl, setRegisteredPhotoUrl] = useState(null);
  const [lastResult, setLastResult] = useState(null);
  const [faceBox, setFaceBox] = useState(null);

  const [successCount, setSuccessCount] = useState(0);
  const [errorCount, setErrorCount] = useState(0);
  const [frameCount, setFrameCount] = useState(0);
  const [lastDetectionTime, setLastDetectionTime] = useState(null);
  const [errorMsg, setErrorMsg] = useState(null);

  // ==================== AUDIO FEEDBACK ====================
  const playSound = useCallback((type) => {
    try {
      const ctx = new (window.AudioContext || window.webkitAudioContext)();
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();

      if (type === 'success') {
        osc.type = 'sine';
        osc.frequency.setValueAtTime(800, ctx.currentTime);
        setTimeout(() => osc.frequency.setValueAtTime(1250, ctx.currentTime + 0.1), 80);
        gain.gain.value = 0.3;
      } else if (type === 'warning') {
        osc.type = 'triangle';
        osc.frequency.setValueAtTime(650, ctx.currentTime);
        gain.gain.value = 0.25;
      } else {
        osc.type = 'sawtooth';
        osc.frequency.setValueAtTime(420, ctx.currentTime);
        gain.gain.value = 0.22;
      }

      const filter = ctx.createBiquadFilter();
      filter.type = 'lowpass';
      filter.frequency.value = 2000;

      osc.connect(filter).connect(gain).connect(ctx.destination);
      osc.start();

      setTimeout(() => {
        gain.gain.linearRampToValueAtTime(0.001, ctx.currentTime + 0.4);
        osc.stop(ctx.currentTime + 0.5);
      }, type === 'success' ? 350 : 250);
    } catch (e) {
      console.warn('Audio non disponible');
    }
  }, []);

  // ==================== DÉMARRAGE CAMÉRA ====================
  const startCamera = async () => {
    try {
      setErrorMsg(null);
      setLoading(true);

      const stream = await navigator.mediaDevices.getUserMedia({
        video: { facingMode: "user" },
        audio: false,
      });

      streamRef.current = stream;
      if (videoRef.current) {
        videoRef.current.srcObject = stream;

        videoRef.current.onloadedmetadata = async () => {
          setCameraActive(true);
          setLoading(false);

          try {
            await videoRef.current.play();
          } catch (playErr) {
            console.warn('Play manuel requis', playErr);
          }

          // Lancer le mode auto après démarrage caméra
          setAutoMode(true);
          if (addNotification) addNotification('✅ Caméra démarrée - Scan automatique activé', 'success');
        };
      }
    } catch (err) {
      console.error('Erreur caméra:', err);
      let msg = 'Impossible d\'accéder à la caméra';
      if (err.name === 'NotAllowedError') msg = 'Permission caméra refusée';
      if (err.name === 'NotFoundError') msg = 'Aucune caméra détectée';

      setErrorMsg(msg);
      setLoading(false);
      if (addNotification) addNotification(msg, 'error');
    }
  };

  // ==================== ARRÊT TOTAL ====================
  const stopAll = () => {
    if (timeoutRef.current) {
      clearTimeout(timeoutRef.current);
      timeoutRef.current = null;
    }
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
      streamRef.current = null;
    }
    if (videoRef.current) videoRef.current.srcObject = null;

    setCameraActive(false);
    setAutoMode(false);
    setStatus('idle');
    setFaceBox(null);
  };

  // ==================== BOUCLE DE CAPTURE ADAPTATIVE ====================
  const startCaptureLoop = useCallback(() => {
    if (!autoMode || !cameraActive) return;

    const captureFrame = async () => {
      if (!videoRef.current) return;

      try {
        const canvas = document.createElement('canvas');
        canvas.width = videoRef.current.videoWidth || 1280;
        canvas.height = videoRef.current.videoHeight || 720;

        const ctx = canvas.getContext('2d');
        ctx.drawImage(videoRef.current, 0, 0);

        const imageBase64 = canvas.toDataURL('image/jpeg', 0.82); // Image brute

        setFrameCount(prev => prev + 1);

        const response = await axios.post('/api/recognize/', {
          image: imageBase64.split(',')[1],
        });

        const data = response.data;
        const confidence = data.confidence || 0;

        if (data.face_box) setFaceBox(data.face_box);

        if (data.success && data.student) {
          // Succès complet
          setCapturedImage(imageBase64);
          setRegisteredPhotoUrl(data.registered_photo_url || null);
          setLastDetectionTime(new Date().toLocaleTimeString());
          setLastResult(data);
          setStatus('success');
          setSuccessCount(prev => prev + 1);

          playSound('success');
          addNotification(`✅ ${data.student} marqué présent`, 'success');

          setAutoMode(false);
          setTimeout(() => setAutoMode(true), 4500);
        } 
        else if (confidence >= CONFIDENCE_THRESHOLD) {
          // Visage détecté mais faible confiance
          setCapturedImage(imageBase64);
          setRegisteredPhotoUrl(data.registered_photo_url || null);
          setStatus('warning');
          setErrorMsg(`Visage détecté mais confiance faible (${(confidence * 100).toFixed(1)}%)`);
          setErrorCount(prev => prev + 1);
          playSound('warning');

          // Mode rapide
          if (timeoutRef.current) clearTimeout(timeoutRef.current);
          timeoutRef.current = setTimeout(captureFrame, CAPTURE_INTERVAL_FAST);
          return;
        } 
        else {
          // Non reconnu
          setCapturedImage(imageBase64);
          setStatus('error');
          setErrorMsg("Visage non reconnu");
          setErrorCount(prev => prev + 1);
          playSound('error');
        }
      } catch (err) {
        const msg = err.response?.data?.message || "Erreur serveur";
        setErrorMsg(msg);
        setStatus('error');
        setErrorCount(prev => prev + 1);
      }

      // Prochaine capture avec intervalle par défaut
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
      timeoutRef.current = setTimeout(captureFrame, CAPTURE_INTERVAL_DEFAULT);
    };

    // Lancer la première capture
    if (timeoutRef.current) clearTimeout(timeoutRef.current);
    timeoutRef.current = setTimeout(captureFrame, 300);
  }, [autoMode, cameraActive, addNotification, playSound]);

  // Lancer la boucle quand autoMode change
  useEffect(() => {
    if (autoMode && cameraActive) {
      startCaptureLoop();
    } else if (timeoutRef.current) {
      clearTimeout(timeoutRef.current);
    }
  }, [autoMode, cameraActive, startCaptureLoop]);

  // ==================== CAPTURE MANUELLE ====================
  const handleManualCapture = async () => {
    if (!videoRef.current || loading) return;

    setLoading(true);
    setErrorMsg(null);

    try {
      const canvas = document.createElement('canvas');
      canvas.width = videoRef.current.videoWidth || 1280;
      canvas.height = videoRef.current.videoHeight || 720;
      const ctx = canvas.getContext('2d');
      ctx.drawImage(videoRef.current, 0, 0);

      const imageBase64 = canvas.toDataURL('image/jpeg', 0.88);
      setCapturedImage(imageBase64);

      const response = await axios.post('/api/recognize/', {
        image: imageBase64.split(',')[1],
      });

      const data = response.data;
      const confidence = data.confidence || 0;

      if (data.success && data.student) {
        setLastResult(data);
        setRegisteredPhotoUrl(data.registered_photo_url);
        setLastDetectionTime(new Date().toLocaleTimeString());
        setStatus('success');
        setSuccessCount(prev => prev + 1);
        playSound('success');
        addNotification(`✅ ${data.student} marqué présent`, 'success');
      } else if (confidence >= CONFIDENCE_THRESHOLD) {
        setStatus('warning');
        setErrorMsg(`Visage détecté mais confiance faible (${(confidence * 100).toFixed(1)}%)`);
        setErrorCount(prev => prev + 1);
        playSound('warning');
      } else {
        setStatus('error');
        setErrorMsg("Visage non reconnu");
        setErrorCount(prev => prev + 1);
        playSound('error');
      }
    } catch (err) {
      const msg = "Erreur lors de la capture";
      setErrorMsg(msg);
      setStatus('error');
      setErrorCount(prev => prev + 1);
      playSound('error');
    } finally {
      setLoading(false);
    }
  };

  // ==================== RENDER PHOTO ENREGISTRÉE ====================
  const RegisteredPhoto = () => {
    if (registeredPhotoUrl) {
      return <img src={registeredPhotoUrl} alt="Enregistrée" style={styles.photo} />;
    }
    return (
      <div style={styles.placeholder}>
        <div style={styles.silhouette}>👤</div>
        <p>Photo de référence</p>
      </div>
    );
  };

  // Nettoyage au démontage
  useEffect(() => {
    return () => {
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
      if (streamRef.current) {
        streamRef.current.getTracks().forEach(track => track.stop());
      }
    };
  }, []);

  return (
    <div style={styles.container}>
      <h1 style={styles.title}>👤 Reconnaissance Faciale - Présence</h1>

      <div style={styles.videoContainer}>
        <video
          ref={videoRef}
          autoPlay
          playsInline
          muted
          style={styles.video}
          aria-label="Flux vidéo de la caméra"
        />
        <canvas ref={overlayCanvasRef} style={styles.overlayCanvas} />

        {cameraActive && (
          <div style={{
            ...styles.statusBadge,
            backgroundColor: status === 'success' ? COLORS.success :
                            status === 'warning' ? COLORS.warning :
                            status === 'error' ? COLORS.error : '#10B981'
          }}>
            {status === 'success' ? '✅ Reconnu' :
             status === 'warning' ? '⚠️ Confiance faible' :
             status === 'error' ? '❌ Non reconnu' : '🔄 Scanning...'}
          </div>
        )}
      </div>

      <div style={styles.controls}>
        {!cameraActive ? (
          <button onClick={startCamera} disabled={loading} style={styles.btnStart} aria-label="Démarrer la caméra et le scan automatique">
            {loading ? '⏳ Démarrage...' : '▶️ Démarrer Auto'}
          </button>
        ) : (
          <>
            <button onClick={handleManualCapture} disabled={loading} style={styles.btnPrimary} aria-label="Capturer une image maintenant">
              {loading ? '⏳ Traitement...' : '📸 Capturer maintenant'}
            </button>

            <button
              onClick={() => setAutoMode(!autoMode)}
              style={{
                ...styles.btn,
                backgroundColor: autoMode ? COLORS.error : '#22C55E'
              }}
              aria-label={autoMode ? "Arrêter le scan automatique" : "Reprendre le scan automatique"}
            >
              {autoMode ? '⏹ Arrêter Auto' : '▶️ Reprendre Auto'}
            </button>

            <button onClick={stopAll} style={styles.btnDanger} aria-label="Fermer complètement la caméra">
              🛑 Fermer Caméra
            </button>
          </>
        )}
      </div>

      {/* Comparaison photos */}
      {capturedImage && (
        <div style={styles.comparison}>
          <div style={styles.photoPair}>
            <div>
              <p style={styles.photoLabel}>📸 Photo capturée</p>
              <img src={capturedImage} alt="capturée" style={styles.photo} />
            </div>
            <div>
              <p style={styles.photoLabel}>📁 Photo enregistrée</p>
              <RegisteredPhoto />
            </div>
          </div>
        </div>
      )}

      {/* Résultat */}
      {lastResult && status === 'success' && (
        <div style={styles.successBox}>
          <h3>✅ {lastResult.student} marqué présent</h3>
          <p><strong>Email :</strong> {lastResult.email || 'N/A'}</p>
          <p><strong>Confiance :</strong> {(lastResult.confidence * 100).toFixed(1)}%</p>
          <p><strong>ID Présence :</strong> {lastResult.attendance_id}</p>
          <p><strong>Heure :</strong> {lastDetectionTime}</p>
        </div>
      )}

      {errorMsg && (
        <div style={status === 'warning' ? styles.warningBox : styles.errorBox}>
          {status === 'warning' ? '⚠️' : '❌'} {errorMsg}
        </div>
      )}

      {/* Stats */}
      <div style={styles.stats}>
        <div>Dernière détection : <strong>{lastDetectionTime || '—'}</strong></div>
        <div>Succès : <strong style={{color: COLORS.success}}>{successCount}</strong></div>
        <div>Échecs : <strong style={{color: COLORS.error}}>{errorCount}</strong></div>
        <div>Frames : <strong>{frameCount}</strong></div>
      </div>

      {/* Debug */}
      <div style={styles.debug}>
        Caméra : {cameraActive ? 'Active' : 'Inactive'} | 
        Mode Auto : {autoMode ? 'ON' : 'OFF'} | 
        Status : {status}
      </div>

      <style>{`
        @keyframes fadeIn {
          from { opacity: 0; transform: translateY(10px); }
          to { opacity: 1; transform: translateY(0); }
        }
      `}</style>
    </div>
  );
};

const styles = {
  container: { padding: '30px', maxWidth: '1100px', margin: '0 auto', fontFamily: 'system-ui, Arial, sans-serif' },
  title: { textAlign: 'center', fontSize: '1.9rem', marginBottom: '25px', color: '#1E2937' },

  videoContainer: { position: 'relative', borderRadius: '16px', overflow: 'hidden', boxShadow: '0 10px 30px rgba(0,0,0,0.25)', background: '#000', marginBottom: '25px' },
  video: { width: '100%', display: 'block' },
  overlayCanvas: { position: 'absolute', top: 0, left: 0, width: '100%', height: '100%', pointerEvents: 'none' },

  statusBadge: {
    position: 'absolute',
    top: '20px',
    right: '20px',
    color: 'white',
    padding: '10px 20px',
    borderRadius: '9999px',
    fontWeight: 'bold'
  },

  controls: { display: 'flex', gap: '12px', flexWrap: 'wrap', marginBottom: '25px' },
  btn: { flex: 1, padding: '16px', border: 'none', borderRadius: '12px', color: 'white', fontWeight: '600', cursor: 'pointer', fontSize: '1.02rem' },
  btnPrimary: { backgroundColor: '#4F46E5' },
  btnStart: { backgroundColor: '#10B981', flex: 1, padding: '16px', border: 'none', borderRadius: '12px', color: 'white', fontWeight: '600', cursor: 'pointer' },
  btnDanger: { backgroundColor: '#475569' },

  comparison: { margin: '25px 0' },
  photoPair: { display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '20px' },
  photoLabel: { textAlign: 'center', marginBottom: '10px', fontWeight: '500' },
  photo: { width: '100%', borderRadius: '12px', border: '3px solid #E2E8F0' },

  placeholder: {
    width: '100%',
    height: '300px',
    backgroundColor: '#F3F4F6',
    border: '3px dashed #9CA3AF',
    borderRadius: '12px',
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'center',
    justifyContent: 'center',
    color: '#6B7280'
  },
  silhouette: { fontSize: '5rem', opacity: 0.6 },

  successBox: { animation: 'fadeIn 0.4s', background: '#F0FDF4', borderLeft: '6px solid #10B981', padding: '20px', borderRadius: '12px', margin: '20px 0' },
  warningBox: { animation: 'fadeIn 0.4s', background: '#FEFCE8', borderLeft: '6px solid #F59E0B', padding: '20px', borderRadius: '12px', margin: '20px 0' },
  errorBox: { animation: 'fadeIn 0.4s', background: '#FEF2F2', borderLeft: '6px solid #EF4444', padding: '20px', borderRadius: '12px', margin: '20px 0' },

  stats: { display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '15px', margin: '25px 0', fontSize: '1.05rem' },
  debug: { background: '#F1F5F9', padding: '15px', borderRadius: '10px', fontSize: '0.9rem', color: '#64748B' }
};

export default CameraRecognition;
